// HomeFragment is one sanitized content panel for the Portal Home tab.
// ChalNN is "" for any static (non-per-challenge) panel and the
// zero-padded challenge number ("01".."11") for a per-challenge
// rule-explain panel, so the Home pane renderer can group/order
// rule-explain panels by challenge without re-parsing the ID string.
// StaticPanels is empty as of P24 (REFACTORING.md P24 §2: intro/cheatsheet
// moved to internal/homefragments.TutorialChapters / the Tutorial tab), so
// today every HomeFragment in practice has ChalNN != "" — but the ChalNN==""
// shape stays supported for any future Home-only static panel.
type HomeFragment struct {
	ID     string
	Label  string
	HTML   string
	ChalNN string
}

// HomeFragments is every gen-time-rendered Home panel, in manifest order
// (static panels first, then rule-explain panels sorted by challenge
// number). A challenge with no rule-explain.md simply has no entry here —
// fail-soft, per home-fragments.yaml; the Home pane must not synthesize a
// placeholder for a missing entry.
var HomeFragments = []HomeFragment{
	{ID: "rule_explain_01_initial_recon", Label: "🔍 なぜ発火するか", ChalNN: "01", HTML: "<h3>ルールの読み方</h3>\n<p>このルール <code>Contact K8S API Server From Container</code> の <code>condition</code> を、左から\n論理積 (<code>and</code>) で読み解く。すべて満たしたイベントだけがアラートになる。</p>\n<table>\n<thead>\n<tr>\n<th>condition の断片</th>\n<th>意味</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>evt.type=connect</code></td>\n<td>ネットワーク接続を張る <code>connect(2)</code> システムコールを見ている。実際にデータを送ったかは問わず、<strong>接続を開いた瞬間</strong>が対象</td>\n</tr>\n<tr>\n<td><code>fd.typechar=4</code> / <code>=6</code></td>\n<td>接続先ファイルディスクリプタが IPv4 (<code>4</code>) または IPv6 (<code>6</code>) ソケットであること (ローカルソケット等を除外)</td>\n</tr>\n<tr>\n<td><code>container</code></td>\n<td>ホスト上の素のプロセスではなく、<strong>コンテナ内</strong>からの接続であること</td>\n</tr>\n<tr>\n<td><code>k8s_api_server</code></td>\n<td>接続先が Kubernetes API Server の宛先に一致する (マクロで定義された IP/ポート)</td>\n</tr>\n<tr>\n<td><code>not k8s_containers</code></td>\n<td>送信元が kube-system 等の<strong>既知のコントロールプレーン Pod ではない</strong> — 一般ワークロードからの接続だけを残す</td>\n</tr>\n<tr>\n<td><code>not user_known_...</code></td>\n<td>運用者が「これは正常」と登録した例外に該当しない</td>\n</tr>\n</tbody>\n</table>\n<p><code>output</code> 行はアラートに添える証拠フィールドだ。<code>connection=%fd.name</code> で接続先、\n<code>process=%proc.name</code> / <code>command=%proc.cmdline</code> で実行主体、<code>user=%user.name</code> で\nどのユーザが動かしたかが記録される。<strong>なぜ発火したかを後から説明できる</strong>のが\nFalco の output の役割で、SOC はこれを見て一次トリアージする。</p>\n<h3>なぜ発火するのか</h3>\n<p>このミッションのコンテナは ServiceAccount を持たない。API Server へ <code>connect</code> を\n開いた時点で <code>not k8s_containers</code> を通過し、上の条件がすべて真になって発火する。\n認証が 401 で弾かれても <strong>接続イベント自体</strong>が検知対象なので、応答内容は無関係だ。</p>\n<h3>Sysdig のマネージドルールでのカバー</h3>\n<p>このルールは Falco コミュニティルールセットに含まれ、Sysdig Secure の\nマネージドポリシー (Sysdig Runtime Threat Detection) にそのまま同梱される。\nつまり<strong>自分でルールを書かなくても</strong>、Sysdig を入れた環境ではコンテナからの\n異常な API Server 接触がデフォルトで検知・可視化される。Sysdig 側ではさらに\nプロセスツリーや Kubernetes メタデータ (Pod / Namespace / ServiceAccount) が\nイベントに紐付き、トリアージが一段速くなる。</p>"},
	{ID: "rule_explain_03_stealth_read", Label: "🔍 なぜ発火するか", ChalNN: "03", HTML: "<h3>ルールの読み方</h3>\n<p>これは <strong>回避 (evade) ミッション</strong>。発火させてはいけないルール\n<code>Read sensitive file untrusted</code> が、何を見て何を見ていないかを理解すると、\nすり抜けの原理が見えてくる。</p>\n<table>\n<thead>\n<tr>\n<th>condition の断片</th>\n<th>意味</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>open_read</code></td>\n<td>ファイルを<strong>読み取り目的で開く</strong> (<code>open</code>/<code>openat</code>) イベント</td>\n</tr>\n<tr>\n<td><code>sensitive_files</code></td>\n<td>開いた <strong>path</strong> が機微ファイルのパターン (<code>/etc/shadow</code>, <code>/etc/sudoers</code> 等) に一致</td>\n</tr>\n<tr>\n<td><code>proc_name_exists</code></td>\n<td>プロセス名が取れている (異常イベントの除外)</td>\n</tr>\n<tr>\n<td><code>not proc.name in (...)</code></td>\n<td><code>sshd</code> / パッケージ管理 / シェル等、<strong>正当に機微ファイルを触るバイナリ</strong>を大量に除外</td>\n</tr>\n<tr>\n<td><code>not ... (多数の例外)</code></td>\n<td>Ansible・Chef・cron 等、運用ツールによる正常アクセスを除外</td>\n</tr>\n</tbody>\n</table>\n<p>判定の要は <code>sensitive_files</code> が <strong><code>fd.name</code> (open に渡した path 文字列)</strong> で\nマッチする点だ。<code>output</code> の <code>file=%fd.name</code> を見ればわかるとおり、Falco が\n記録するのは<strong>解決後の実体パスではなく、呼び出し側が渡したパス文字列</strong>。</p>\n<h3>なぜ発火しない (リスクが低い) のか</h3>\n<p>同じファイル本体 (inode) には、<code>/etc/shadow</code> 以外の path 経由でも到達できる。\nLinux にはプロセス視点の代替パス (プロセスの mount namespace ルートを指す\n<code>/proc/&lt;pid&gt;/root/...</code> など) が存在し、そこを通すと <code>fd.name</code> が\n<code>/etc/shadow</code> パターンにマッチしなくなる — だから<strong>このルール</strong>は鳴らない。</p>\n<p>ただし、これは「検知を消した」のではなく「<strong>このルールの視野の外に出た</strong>」だけだ。\nリスクが相対的に低いと言えるのは、(1) 攻撃者側に「path 判定を回避する」という\n一手間と知識を強制でき、(2) 別レイヤ (下記) で捕捉の機会が残るから。path 一本に\n依存した検知は脆く、多層で見るべき、という教訓がこのミッションの核心だ。</p>\n<h3>Sysdig のマネージドルールでのカバー</h3>\n<p>path 文字列だけに頼るこの回避は、<strong>フィールドを変えたルール</strong>で塞げる。Sysdig の\nマネージドルールセットは同じ機微ファイル読み出しを複数の角度から監視しており、\nシナリオ全体としては次の層でカバーされる。</p>\n<ul>\n<li><strong>代替パス読み出しの明示検知</strong> — <code>/proc/*/root/...</code> のようなプロキシパス経由の\n機微ファイルアクセスを狙って捕捉するルールが用意されている。</li>\n<li><strong>inode / 実体ベースの判定</strong> — path 文字列ではなく開かれた対象の実体で評価する\n設計に寄せることで、別名でのアクセスを吸収する。</li>\n<li><strong>相関</strong> — Sysdig Secure は単発イベントを Pod / Namespace / プロセスツリーと\n紐付けるため、「機微ファイルへの回避的アクセス」というパターンとして浮かび上がる。</li>\n</ul>\n<p>要するに、<strong>自作の単一ルールを path で書くと抜けられるが、Sysdig のマネージド\nポリシーはこのシナリオを別フィールド・別ルールで面として押さえている</strong>。</p>"},
	{ID: "rule_explain_04_key_search", Label: "🔍 なぜ発火するか", ChalNN: "04", HTML: "<h3>ルールの読み方</h3>\n<p><code>Search Private Keys or Passwords</code> の <code>condition</code> は、<code>spawned_process</code>\n(新しいプロセスが起動した <code>execve(2)</code> イベント) を起点に、以下のいずれかに\n当てはまるかを見ている。</p>\n<table>\n<thead>\n<tr>\n<th>condition の断片</th>\n<th>意味</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>spawned_process</code></td>\n<td>プロセスが新規に <code>exec</code> された瞬間を対象にする (常駐プロセスの中の動きではなく、起動そのもの)</td>\n</tr>\n<tr>\n<td><code>grep_commands and private_key_or_password</code></td>\n<td><code>grep</code> 系コマンドで、かつ引数に鍵・パスワードを示すパターン (<code>BEGIN ... PRIVATE KEY</code> 等) が含まれる</td>\n</tr>\n<tr>\n<td><code>proc.name = &#34;find&#34; and proc.args contains &#34;id_rsa&#34;</code> (等)</td>\n<td><code>find</code> コマンドで、引数に <code>id_rsa</code> / <code>id_dsa</code> / <code>id_ed25519</code> / <code>id_ecdsa</code> を含む</td>\n</tr>\n</tbody>\n</table>\n<p>ここで重要なのは、判定材料が <strong><code>proc.args</code> / <code>proc.cmdline</code> = 起動時のコマンドライン\n文字列</strong>であることだ。ファイルが実在するかも、実際にヒットしたかも見ていない。\n<strong>「鍵を探そうとするコマンドを打った」という意図そのもの</strong>を検知する。</p>\n<p><code>output</code> の <code>command=%proc.cmdline</code> にそのコマンドライン全体が入るので、SOC は\n「何を探そうとしたか」をアラートから直接読める。</p>\n<h3>なぜ発火するのか</h3>\n<p><code>find / -name id_rsa</code> のように打つと、<code>exec</code> されたコマンドラインに <code>id_rsa</code> が\n残る。それが <code>proc.args contains &#34;id_rsa&#34;</code> に一致して発火する。結果が空でも、\n対象ファイルが無くても、<strong>コマンドラインの文字列が条件を満たした瞬間</strong>に鳴る。</p>\n<p>これは「コマンドラインシグネチャ型」の検知で、素早く広く網を張れる反面、\n引数から特徴語を消されると抜けられる (それを体験するのが Mission 05)。</p>\n<h3>Sysdig のマネージドルールでのカバー</h3>\n<p>このルールも Sysdig Secure のマネージドポリシーに標準搭載されている。認証情報\n探索 (MITRE ATT&amp;CK T1552.001 — Credentials In Files) の代表的なベースライン検知\nとして、追加設定なしで有効になる。Sysdig 側ではこの単発イベントを\n<strong>プロセスツリーや後続の振る舞い</strong>と関連付けるため、「鍵探索 → 実際の読み出し →\n外部送信」という連鎖として攻撃ストーリーを組み立てられる。</p>"},
	{ID: "rule_explain_05_silent_search", Label: "🔍 なぜ発火するか", ChalNN: "05", HTML: "<h3>ルールの読み方</h3>\n<p>これは <strong>回避 (evade) ミッション</strong>。Mission 04 で発火させた\n<code>Search Private Keys or Passwords</code> を、今度は<strong>鳴らさずに</strong>目的を果たす。\nまず、このルールが「何を根拠に」判定しているかを押さえる。</p>\n<table>\n<thead>\n<tr>\n<th>condition の断片</th>\n<th>意味</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><code>spawned_process</code></td>\n<td>プロセスが新規に <code>exec</code> された瞬間を対象にする</td>\n</tr>\n<tr>\n<td><code>grep_commands and private_key_or_password</code></td>\n<td><code>grep</code> 系で、かつ引数に鍵/パスワードのパターンを含む</td>\n</tr>\n<tr>\n<td><code>proc.name = &#34;find&#34; and proc.args contains &#34;id_rsa&#34;</code> (等)</td>\n<td><code>find</code> で、引数に鍵ファイル名を含む</td>\n</tr>\n</tbody>\n</table>\n<p>Mission 04 と同じく、判定材料は <strong><code>proc.args</code> / <code>proc.cmdline</code> = exec 時の\nコマンドライン文字列</strong>だ。<code>output</code> の <code>command=%proc.cmdline</code> にも、その起動時の\n引数がそのまま残る。ルールは**「特徴語を含むコマンドラインで起動されたこと」**を\n見ており、その後にプロセスが何を読んだかまでは追っていない。</p>\n<h3>なぜ発火しない (リスクが低い) のか</h3>\n<p>ファイルの中身を得る方法は「ファイル名を引数に渡す」だけではない。<strong>引数に機微な\nファイル名を一切載せずに</strong>同じ中身へ到達する経路がシェルには複数ある (入力の\n受け渡しの仕方を変える等)。すると exec されたプロセスの <code>proc.cmdline</code> には\n特徴語 (<code>id_rsa</code> 等) が現れず、<code>proc.args contains &#34;id_rsa&#34;</code> が偽になって発火しない。</p>\n<p>これも「検知を破壊した」のではなく「<strong>コマンドラインシグネチャの死角に入った</strong>」\nだけだ。リスクが低いと言えるのは、(1) 攻撃者に引数を隠すという追加の工夫を要求でき、\n(2) 実際のファイル読み出しは下記の別ルールで捕捉余地が残るから。<strong>コマンドライン\n文字列だけに依存した検知は回避されやすい</strong>、という点がこのミッションの学びだ。</p>\n<h3>Sysdig のマネージドルールでのカバー</h3>\n<p>コマンドライン隠蔽で抜けても、<strong>「実際に機微ファイルを読んだ」という行為</strong>は別の\nルールで捕まえられる。Sysdig のマネージドルールセットはこのシナリオを面で押さえる。</p>\n<ul>\n<li><strong>ファイル読み出しベースの検知</strong> — <code>Read sensitive file untrusted</code> のように、\nコマンドラインではなく <strong>open された対象</strong>を見るルールが、鍵ファイルの読み出し\nそのものを捕捉する (cmdline を隠しても読み出しは残る)。</li>\n<li><strong>相関</strong> — Sysdig Secure は「鍵探索の試み」「鍵ファイルの読み出し」「外部への\n送信」を同一プロセスツリー上で関連付け、コマンドライン検知が 1 つ抜けても\nシナリオ全体としてアラートを積み上げる。</li>\n</ul>\n<p>つまり、<strong>cmdline 一本で書いた自作ルールは引数隠しで抜けられるが、Sysdig の\nマネージドポリシーは読み出しイベント + 相関でこのシナリオをカバーする</strong>。</p>"},
}
